/**
 * Shared screenshot-evidence naming and discovery helpers.
 *
 * The repository has two accepted filename shapes:
 *   - {slug}-{locale}.png
 *   - {slug}-{locale}-{theme}-{viewport}.png
 *
 * Keep parsing here so Terrain, Analysis, Page Health, and the institutional
 * activation validator cannot silently disagree about which files are proof.
 *
 * LATTICE:BEGIN — generated by lib/build-lattice-headers.js from docs/lattice-map.json. Do not hand-edit; edit the JSON and regenerate.
 *   role      : shared screenshot-evidence filename parser and deterministic projection helper
 *   reads     : (none)
 *   writes    : (none)
 *   loaded-by : lib/check-institutional-surfaces.js
 *               lib/build-page-health.js
 *               lib/build-terrain-map.js
 *               lib/build-analysis-index.js
 *               tests/36-build-analysis-index.test.js
 *   tested-by : tests/28-build-terrain-map.test.js
 *               tests/36-build-analysis-index.test.js
 *               tests/44-page-health.test.js
 *               tests/54-institutional-surfaces.test.js
 *
 *   CHANGE MAP — if you touch X here, also check:
 *     legacy or matrix filename grammar changed:
 *       - lib/check-institutional-surfaces.js (activation evidence path)
 *       - lib/build-page-health.js (locale and exact-file health evidence)
 *       - lib/build-terrain-map.js (representative screen plus exact evidence records)
 *       - lib/build-analysis-index.js (per-page evidence projection)
 *       - tests/28, tests/44, and tests/54
 * LATTICE:END
 */

'use strict';

const SCREENSHOT_PREFIX = 'docs/screenshots/';

function evidenceFilename(slug, locale, theme, viewport) {
  return `${slug}-${locale}-${theme}-${viewport}.png`;
}

function parseScreenshotFilename(filename) {
  if (typeof filename !== 'string') return null;

  const matrix = filename.match(/^(.+)-([a-z]{2})-([a-z0-9]+(?:-[a-z0-9]+)*)-([1-9][0-9]*)\.png$/);
  if (matrix) {
    return {
      slug: matrix[1],
      locale: matrix[2],
      theme: matrix[3],
      viewport: Number(matrix[4]),
      kind: 'matrix',
      path: SCREENSHOT_PREFIX + filename,
    };
  }

  const legacy = filename.match(/^(.+)-([a-z]{2})\.png$/);
  if (!legacy) return null;
  return {
    slug: legacy[1],
    locale: legacy[2],
    theme: null,
    viewport: null,
    kind: 'legacy',
    path: SCREENSHOT_PREFIX + filename,
  };
}

function findScreenshotEvidence(files) {
  const bySlug = {};
  for (const filename of (files || []).slice().sort()) {
    const record = parseScreenshotFilename(filename);
    if (!record) continue;
    bySlug[record.slug] = bySlug[record.slug] || [];
    bySlug[record.slug].push(record);
  }
  return bySlug;
}

function representativeScreenshots(evidenceBySlug) {
  const bySlug = {};
  for (const slug of Object.keys(evidenceBySlug || {}).sort()) {
    const byLocale = {};
    for (const record of evidenceBySlug[slug]) {
      byLocale[record.locale] = byLocale[record.locale] || [];
      byLocale[record.locale].push(record);
    }

    const representatives = {};
    for (const locale of Object.keys(byLocale).sort()) {
      const candidates = byLocale[locale].slice().sort((a, b) => {
        if (a.kind !== b.kind) return a.kind === 'legacy' ? -1 : 1;
        if ((a.viewport || 0) !== (b.viewport || 0)) return (b.viewport || 0) - (a.viewport || 0);
        return String(a.theme || '').localeCompare(String(b.theme || '')) || a.path.localeCompare(b.path);
      });
      representatives[locale] = candidates[0].path;
    }
    bySlug[slug] = representatives;
  }
  return bySlug;
}

function findScreenshots(files) {
  return representativeScreenshots(findScreenshotEvidence(files));
}

module.exports = {
  SCREENSHOT_PREFIX,
  evidenceFilename,
  parseScreenshotFilename,
  findScreenshotEvidence,
  representativeScreenshots,
  findScreenshots,
};

